    'Kauden ankkuri (6–12 kk) — yksi selkeä suunta koko kaudelle, mihin pelaaja tähtää. Jaksofokukset (mesot) rakentavat tätä kohti pala kerrallaan.': 'Säsongens ankare (6–12 mån) — en tydlig riktning för hela säsongen, det spelaren siktar mot. Periodfokusen (mesocyklerna) bygger mot detta bit för bit.',
    'Aseta yksi strateginen kauden tavoite. Moottori ehdottaa datasta (heikoin/vahvin) tai valitse käsin. §37: kauden tavoite (makro) sovitaan yhdessä — VP vahvistaa, valmentaja ehdottaa.': 'Sätt ett strategiskt säsongsmål. Motorn föreslår utifrån data (svagast/starkast) eller välj för hand. §37: säsongsmålet (makro) kommer man överens om tillsammans — FU bekräftar, tränaren föreslår.',
    'Pidä kauden tavoite laajana ja pysyvänä — jaksofokus muuttuu 4–8 vk välein, kauden tavoite ei.': 'Håll säsongsmålet brett och bestående — periodfokuset byts var 4–8 vecka, säsongsmålet inte.',
    'Jaksofokus · aktiivinen meso': 'Periodfokus · aktiv meso',
    'Tämän jakson (4–8 vk) yksi painopiste — mitä kentällä juuri nyt harjoitellaan. Kolme valintaa: <b>1 · Domeeni</b> (kumpaa jakso kehittää: fyysinen / teknis-taktinen / psyykkinen / sosiaalinen), <b>2 · Painopiste</b> (moottorin logiikka: korjaa heikkous / jalosta vahvuus / pelipaikka), <b>3 · Teema</b> + kesto.': 'Denna periods (4–8 v) enda tyngdpunkt — vad som tränas på planen just nu. Tre val: <b>1 · Domän</b> (vad perioden utvecklar: fysiskt / tekniskt-taktiskt / psykiskt / socialt), <b>2 · Tyngdpunkt</b> (motorns logik: åtgärda svaghet / förädla styrka / position), <b>3 · Tema</b> + längd.',
    'Ikävaihe ohjaa <strong>ehdotusta</strong>, ei estä valintaa — teema on aina yliajettavissa. Yksi jaksofokus kerrallaan; domeenin vaihto arkistoi vanhan jakson.': 'Åldersfasen styr <strong>förslaget</strong>, den hindrar inte valet — temat går alltid att åsidosätta. Ett periodfokus i taget; byte av domän arkiverar den gamla perioden.',
    'Vähemmän on enemmän — fokus näkyy viikossa mutta ei täytä sitä (PDP: less is more).': 'Mindre är mer — fokuset syns i veckan men fyller den inte (PDP: less is more).',
    'Moottori · valitse polku': 'Motorn · välj väg',
    'Moottori ehdottaa jaksofokusta pelaajan datasta: 🎯 korjaa heikkous (heikoin alue) tai 💎 jalosta supervoima (vahvin alue).': 'Motorn föreslår periodfokus utifrån spelarens data: 🎯 åtgärda svaghet (svagaste området) eller 💎 förädla supermakten (starkaste området).',
    'Moottori <strong>ei pakota</strong> — hyväksy ehdotus tai valitse itse. 70/30: heikkoustyö integroidaan vahvuuden pohjalle, ei irrallisena. §28: heikko fyysinen ei tule ehdolle ennen PHV:tä.': 'Motorn <strong>tvingar inte</strong> — godkänn förslaget eller välj själv. 70/30: svaghetsarbetet integreras på styrkans grund, inte som något fristående. §28: svag fysik kommer inte i fråga före PHV.',
    'Ainakin yksi vahvuustavoite jaksoon — ei pelkkää heikkouksien paikkaamista.': 'Minst ett styrkemål per period — inte enbart lappning av svagheter.',
    'Tavoitejakauma · tasapaino': 'Målfördelning · balans',
    'Jakson tavoitteet jaettuna lähteen mukaan: heikkous · vahvuus · pelipaikka. Kukin sessio kertyy jaksofokuksen tavoitteelle (A/B/C) ja koostuu IDP-katselmukseen.': 'Periodens mål fördelade efter källa: svaghet · styrka · position. Varje pass räknas mot periodfokusets mål (A/B/C) och sammanställs till IDP-granskningen.',
    'Tasapaino kunnossa, kun jaksossa on <strong>vähintään yksi vahvuustavoite</strong> — ei pelkkää heikkouksien paikkaamista.': 'Balansen är i skick när perioden innehåller <strong>minst ett styrkemål</strong> — inte enbart lappning av svagheter.',
    '~40 % palvelee jaksofokusta — riittävä toistomäärä ilman että muu kehitys pysähtyy.': '~40 % tjänar periodfokuset — tillräckligt många repetitioner utan att övrig utveckling stannar.',
    'Pelaajan ääni & sitoumus': 'Spelarens röst & åtagande',
    'Pelaajan oma näkökulma osaksi suunnitelmaa: mikä tuntuu vaikealta · missä onnistui · mitä pelaaja itse haluaa. Lopuksi pelaajan sitoumus jaksoon.': 'Spelarens eget perspektiv som del av planen: vad som känns svårt · var hen lyckades · vad spelaren själv vill. Till sist spelarens åtagande för perioden.',
    'Pelaaja kirjoittaa (Pelaaja-app); VP/valmentaja täydentää tarvittaessa. Sitoumus → VP vahvistaa. Autonomiaa tukeva (Deci &amp; Ryan) — suunnitelma tehdään pelaajan kanssa, ei pelaajalle.': 'Spelaren skriver (Spelar-appen); FU/tränaren kompletterar vid behov. Åtagandet → FU bekräftar. Autonomistödjande (Deci &amp; Ryan) — planen görs med spelaren, inte åt spelaren.',
    'Kun pelaaja omistaa "miksi", motivaatio kestää — kysy, älä käske.': 'När spelaren äger sitt ”varför” håller motivationen — fråga, befall inte.',
