    'Viiden liikehallintaketjun — Vauhtiketju, Lähtöketju, Sivuketju, Diagonaaliketju ja Hallintaketju — liikkuvuus ja hallinta, 0–100. Liikevalmiuden ja loukkaantumisriskin mittari; todennetaan harjoitettavuuskartoituksella.': 'Rörlighet och kontroll i fem rörelsekedjor — Fartkedjan, Startkedjan, Sidokedjan, Diagonalkedjan och Kontrollkedjan — 0–100. Mätare för rörelseberedskap och skaderisk; verifieras med träningsbarhetskartläggningen.',
